/**
 * Initialize Claude Code Chats Sync for current workspace
 */
async function initializeClaudeSync(): Promise<void> {
    const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
    if (!workspaceFolder) {
        vscode.window.showErrorMessage('No workspace folder found');
        return;
    }

    const projectPath = workspaceFolder.uri.fsPath;
    const historyFolder = getHistoryFolderPath(projectPath);
    const claudeProjectsDir = getClaudeProjectsDir();
    const normalizedPath = normalizeProjectPath(projectPath);
    const symlinkPath = path.join(claudeProjectsDir, normalizedPath);

    try {
        // Check if symlink already exists
        if (fs.existsSync(symlinkPath)) {
            const stats = fs.lstatSync(symlinkPath);
            if (stats.isSymbolicLink() || stats.isDirectory()) {
                vscode.window.showInformationMessage('Claude Code Chats Sync already initialized');
                return;
            } else {
                vscode.window.showErrorMessage(
                    `A file already exists at Claude Code location: ${symlinkPath}`
                );
                return;
            }
        }

        // Check if there's existing Claude Code history that needs to be migrated
        if (fs.existsSync(claudeProjectsDir)) {
            const existingHistory = fs.readdirSync(claudeProjectsDir);
            if (existingHistory.includes(normalizedPath)) {
                const existingPath = path.join(claudeProjectsDir, normalizedPath);
                const stats = fs.statSync(existingPath);

                // Only migrate if it's a real directory (not a symlink)
                if (stats.isDirectory() && !stats.isSymbolicLink()) {
                    const files = fs.readdirSync(existingPath);
                    const sessionFiles = files.filter(f => f.endsWith('.jsonl'));

                    if (sessionFiles.length > 0 && !fs.existsSync(historyFolder)) {
                        // Existing sessions found - ask user what to do
                        const answer = await vscode.window.showWarningMessage(
                            `Found ${sessionFiles.length} existing Claude Code session(s) in Claude's storage.\n\n` +
                            `Would you like to move them to your project folder?`,
                            'Move to Project',
                            'Link to Existing',
                            'Cancel'
                        );

                        if (answer === 'Move to Project') {
                            // Move existing sessions to project folder
                            await moveExistingSessions(existingPath, historyFolder);
                        } else if (answer === 'Link to Existing') {
                            // Create symlink pointing to existing location (reverse direction)
                            await linkToExistingHistory(existingPath, historyFolder);
                            return;
                        } else {
                            // User canceled
                            return;
                        }
                    }
                }
            }
        }

        // Create history folder if it doesn't exist
        if (!fs.existsSync(historyFolder)) {
            fs.mkdirSync(historyFolder, { recursive: true });
            vscode.window.showInformationMessage(`Created folder: ${historyFolder}`);
        }

        // Ensure .claude/projects directory exists
        if (!fs.existsSync(claudeProjectsDir)) {
            fs.mkdirSync(claudeProjectsDir, { recursive: true });
        }

        // Create symbolic link
        // On Windows: use 'junction' for directory compatibility
        // On Linux/Mac: use 'dir' for symbolic link
        const symlinkType = process.platform === 'win32' ? 'junction' : 'dir';
        fs.symlinkSync(historyFolder, symlinkPath, symlinkType);

        vscode.window.showInformationMessage(
            `✅ Claude Code Chats Sync initialized!\n` +
            `History folder: ${historyFolder}\n` +
            `Linked to: ${symlinkPath}`
        );

        // Add to .gitignore if not present
        await addToGitIgnore(projectPath);

    } catch (error: any) {
        vscode.window.showErrorMessage(
            `Failed to initialize Claude Code Chats Sync: ${error.message}`
        );
    }
}

/**
 * Move existing Claude Code sessions to project folder
 */
async function moveExistingSessions(
    existingPath: string,
    historyFolder: string
): Promise<void> {
    try {
        // Create history folder
        fs.mkdirSync(historyFolder, { recursive: true });

        // Move all session files
        const files = fs.readdirSync(existingPath);
        let movedCount = 0;

        for (const file of files) {
            if (file.endsWith('.jsonl')) {
                const srcPath = path.join(existingPath, file);
                const destPath = path.join(historyFolder, file);
                fs.renameSync(srcPath, destPath);
                movedCount++;
            }
        }

        // Remove old directory if empty
        try {
            const remainingFiles = fs.readdirSync(existingPath);
            if (remainingFiles.length === 0) {
                fs.rmSync(existingPath, { recursive: true });
            }
        } catch {
            // Ignore error if directory can't be removed
        }

        vscode.window.showInformationMessage(
            `✅ Moved ${movedCount} session(s) to project folder`
        );
    } catch (error: any) {
        throw new Error(`Failed to move existing sessions: ${error.message}`);
    }
}

/**
 * Link to existing history (reverse direction)
 * Creates project/.claudeCodeSessions as a symlink to ~/.claude/projects/{normalized}
 */
async function linkToExistingHistory(
    existingPath: string,
    historyFolder: string
): Promise<void> {
    try {
        // Create symlink from project folder to existing location
        const symlinkType = process.platform === 'win32' ? 'junction' : 'dir';
        fs.symlinkSync(existingPath, historyFolder, symlinkType);

        vscode.window.showInformationMessage(
            `✅ Linked to existing Claude Code history!\n` +
            `History location: ${existingPath}\n` +
            `Project link: ${historyFolder}`
        );
    } catch (error: any) {
        throw new Error(`Failed to create link: ${error.message}`);
    }
}

