/**
 * Move or link existing Claude Code history to project folder
 */
async function moveOrLinkExistingHistory(
    existingPath: string,
    historyFolder: string,
    symlinkPath: string,
    forceMove: boolean
): Promise<void> {
    const files = fs.readdirSync(existingPath);
    const sessionFiles = files.filter(f => f.endsWith('.jsonl'));

    const answer = await vscode.window.showInformationMessage(
        `Found ${sessionFiles.length} existing Claude Code session(s).\n\n` +
        `Move them to your project folder, or keep them in Claude's storage?`,
        forceMove ? 'Move' : 'Move to Project',
        'Keep in Claude Storage'
    );

    if (answer === 'Move to Project' || answer === 'Move') {
        // Move existing folder to project
        fs.renameSync(existingPath, historyFolder);

        // Create symlink from Claude location to project folder
        await createSymlink(historyFolder, symlinkPath);

        vscode.window.showInformationMessage(
            `✅ Moved ${sessionFiles.length} session(s) to project folder!\n` +
            `Location: ${historyFolder}`
        );
    } else {
        // Keep in Claude storage - create project folder as symlink to existing location
        const symlinkType = process.platform === 'win32' ? 'junction' : 'dir';
        fs.symlinkSync(existingPath, historyFolder, symlinkType);

        vscode.window.showInformationMessage(
            `✅ Keeping sessions in Claude storage.\n` +
            `Project folder links to: ${existingPath}`
        );
    }
}

/**
 * Create symlink from project folder to Claude Code location
 */
async function createSymlink(
    historyFolder: string,
    symlinkPath: string
): Promise<void> {
    const symlinkType = process.platform === 'win32' ? 'junction' : 'dir';
    fs.symlinkSync(historyFolder, symlinkPath, symlinkType);
}

