    if (fs.existsSync(symlinkPath)) {
        status.push(`✅ Symlink created: ${symlinkPath}`);
    } else {
        status.push(`❌ Symlink not created`);
    }

    vscode.window.showInformationMessage(status.join('\n'), 'OK');
}

